//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.vScrenID = "ULDSTF20501.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    chb_Grp_All.setValue(1);
    scwin.fn_allCheck();

    //chb_Grp_All_2.checked  = true;
    scwin.fn_allCheck_2();

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_SDate_1.text = cGetMinusDate2(vCurDate, 365*2); 	// 일주일전 날짜
    edt_SDate_1.setValue("19000101"); // 일주일전 날짜
    edt_EDate_1.setValue(vCurDate); // 현재날짜

    edt_SDate_2.setValue($c.ut.cGetMinusDate2(vCurDate, 365 * 2)); // 일주일전 날짜
    edt_EDate_2.setValue(vCurDate); // 현재날짜

    dts_DELIST_RSN_CD_1.DataID = encodeURI(scwin.fn_getUrluprsncd());
    dts_DELIST_RSN_CD_1.reset();
    dts_DELIST_RSN_CD_2.DataID = encodeURI(scwin.fn_getUrluprsncd());
    dts_DELIST_RSN_CD_2.reset();
};
scwin.fn_getUrluprsncd = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_SEARCH_UP_DELIST_RSN_CD" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.delist.uprsncd.condition";
    return url;
};
scwin.fn_list_sync = function() {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        /*
        var url = "/ListedSearch.do?method=listStockTradingSuspension&inputMessageId=LISTED_SEARCH_TRD_HALT_OUT";
        url += "&gubun=1";
        url += "&comNm="+comNm.replace( "&" , "＆") ;
        url += "&secuGrpId="+secuGrpId ;
        */
        btn_Search_1.setDisabled(true);
        btn_Search_1.src = "../img/btn_select_d.gif";
        var mktTpCd = "1";
        var secuGrpId = "";
        if ($c.stf.getObjectValue(chb_Grp_St) == 'Y') secuGrpId += 'ST,';
        if ($c.stf.getObjectValue(chb_Grp_Mf) == 'Y') secuGrpId += 'MF,';
        if ($c.stf.getObjectValue(chb_Grp_Rt) == 'Y') secuGrpId += 'RT,';
        if ($c.stf.getObjectValue(chb_Grp_Sc) == 'Y') secuGrpId += 'SC,';
        if ($c.stf.getObjectValue(chb_Grp_Fs) == 'Y') secuGrpId += 'FS,';
        if ($c.stf.getObjectValue(chb_Grp_Dr) == 'Y') secuGrpId += 'DR,';
        if ($c.stf.getObjectValue(chb_Grp_If) == 'Y') secuGrpId += 'IF,';
        if ($c.stf.getObjectValue(chb_Grp_All) == ' Y') secuGrpId = '';
        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_SEARCH_DELIST_ISUR_INST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.listDelisting.kospi.select.condition" + "&{P}param01=" + mktTpCd + "&{P}param02=" + secuGrpId + "&{P}param03=" + secuGrpId + "&{P}param04=" + $c.stf.getObjectValue(edt_SDate_1) + // 시작일자
            "&{P}param05=" + $c.stf.getObjectValue(edt_EDate_1) + // 종료일자
            "&{P}param06=" + $c.stf.getObjectValue(txb_ISUR_CD_1) + // 법인코드
            "&{P}param07=" + $c.stf.getObjectValue(txb_ISUR_CD_1) + // 법인코드
            "&{P}param08=" + $c.stf.getObjectValue(cmb_DELIST_RSN_CD_1) + "&{P}param09=" + $c.stf.getObjectValue(cmb_DELIST_RSN_CD_1);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        var secuGrpId = "";
        btn_Search_2.setDisabled(true);
        btn_Search_2.src = "../img/btn_select_d.gif";
        if ($c.stf.getObjectValue(chb_Grp_St_2) == 'Y') secuGrpId += 'ST,';
        if ($c.stf.getObjectValue(chb_Grp_Mf_2) == 'Y') secuGrpId += 'MF,';
        if ($c.stf.getObjectValue(chb_Grp_Sc_2) == 'Y') secuGrpId += 'SC,';
        if ($c.stf.getObjectValue(chb_Grp_Rt_2) == 'Y') secuGrpId += 'RT,';
        if ($c.stf.getObjectValue(chb_Grp_Dr_2) == 'Y') secuGrpId += 'DR,';
        if ($c.stf.getObjectValue(chb_Grp_Fs_2) == 'Y') secuGrpId += 'FS,';
        if ($c.stf.getObjectValue(chb_Grp_If_2) == 'Y') secuGrpId += 'IF,';
        if ($c.stf.getObjectValue(chb_Grp_Ef_2) == 'Y') secuGrpId += 'EF,FE,';
        if ($c.stf.getObjectValue(chb_Grp_Pf_2) == 'Y') secuGrpId += 'PF,'; // PF jackal_25.05.09
        if ($c.stf.getObjectValue(chb_Grp_Sw_2) == 'Y') secuGrpId += 'SW,';
        if ($c.stf.getObjectValue(chb_Grp_Sr_2) == 'Y') secuGrpId += 'SR,';
        if ($c.stf.getObjectValue(chb_Grp_Ew_2) == 'Y') secuGrpId += 'EW,';
        if ($c.stf.getObjectValue(chb_Grp_Bc_2) == 'Y') secuGrpId += 'BC,';
        /* ETN 추가  [start] */
        if ($c.stf.getObjectValue(chb_Grp_En_2) == 'Y') secuGrpId += 'EN,';
        /* ETN 추가  [ end ] */

        //투자계약증권
        if ($c.stf.getObjectValue(chb_Grp_IC_2) == 'Y') secuGrpId += 'IC,';
        //신탁수익증권
        if ($c.stf.getObjectValue(chb_Grp_TC_2) == 'Y') secuGrpId += 'TC,';
        if ($c.stf.getObjectValue(chb_Grp_All_2) == 'Y') secuGrpId = '';
        /*
        var url = "/ListedSearch.do?method=listStockTradingSuspension&inputMessageId=LISTED_SEARCH_TRD_HALT_OUT";
        url += "&gubun=2";
        url += "&comNm="+comNm.replace( "&" , "＆") ;
        url += "&secuGrpId="+secuGrpId ;
        url += "&startDate="+ getObjectValue(edt_SDate);
        url += "&endDate="+getObjectValue(edt_EDate);
        url += "&depCd="+getObjectValue(cmb_TeamList);
        url += "&empNo="+getObjectValue(cmb_EmpList);
        url += "&listStatCd="+ getObjectValue(rdo_LIST_STAT_CD);
        url += "&rsnCd="+getObjectValue(txb_LD_HALT_RSN_CD);
        */

        var url = "/listingCommon.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listGeneral" + "&outputMessageId=LIST_SEARCH_DELIST_ISU_CD" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.delist.isucd.condition" + "&{P}param01=" + secuGrpId + "&{P}param02=" + secuGrpId + "&{P}param03=" + $c.stf.getObjectValue(txb_ISU_NM_2) + "&{P}param04=" + $c.stf.getObjectValue(txb_ISU_NM_2) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate_2) + // 시작일자
            "&{P}param06=" + $c.stf.getObjectValue(edt_EDate_2) + // 종료일자
            "&{P}param07=" + $c.stf.getObjectValue(cmb_DELIST_RSN_CD_2) + "&{P}param08=" + $c.stf.getObjectValue(cmb_DELIST_RSN_CD_2);
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    }
};
scwin.fn_allCheck = function() {
    var checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs, chb_Grp_If];
    if (chb_Grp_All.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_allCheck_2 = function() {
    var checkArray = [chb_Grp_St_2, chb_Grp_Mf_2, chb_Grp_Sc_2, chb_Grp_Rt_2, chb_Grp_Dr_2, chb_Grp_Fs_2, chb_Grp_Bc_2, chb_Grp_Ef_2, chb_Grp_Pf_2, chb_Grp_Sw_2, chb_Grp_Sr_2, chb_Grp_Ew_2, chb_Grp_En_2, chb_Grp_If_2, chb_Grp_TC_2, chb_Grp_IC_2]; // ETN 추가 :: chb_Grp_En_2 PF 25.05.09
    if (chb_Grp_All_2.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.txb_ISUR_CD_1_onblur = function() {
    if (txb_ISUR_CD_1.getValue() == "") {
        txb_COM_NM_1.setValue("");
    }
};
scwin.img_COM_NM_1_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD_1, txb_COM_NM_1);
};
scwin.btn_Search_1_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate_1, edt_EDate_1)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Search_2_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate_2, edt_EDate_2)) {
        scwin.fn_list_sync();
    }
};
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var Rows;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        Rows = dts_List_1.getTotalRow();
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        Rows = dts_List_2.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(Rows, panel_page);
    //fn_list_sync();

};
