scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
    btn_Search_1.setDisabled(false);
    btn_Search_1.src = "../img/btn_select.gif";
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
    btn_Search_2.setDisabled(false);
    btn_Search_2.src = "../img/btn_select.gif";
};
scwin.dts_DELIST_RSN_CD_1_OnLoadCompleted = function(rowcount) {
    dts_DELIST_RSN_CD_1.insertRow(0);
    dts_DELIST_RSN_CD_1.setCellData(1, "VALUE", "");
    dts_DELIST_RSN_CD_1.setCellData(1, "TEXT", "전체");
};
scwin.dts_DELIST_RSN_CD_2_OnLoadCompleted = function(rowcount) {
    dts_DELIST_RSN_CD_2.insertRow(0);
    dts_DELIST_RSN_CD_2.setCellData(1, "VALUE", "");
    dts_DELIST_RSN_CD_2.setCellData(1, "TEXT", "전체");
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
