scwin.cmb_PeriodTp_1_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp_1, "VALUE", cmb_PeriodTp_1.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate_1, edt_EDate_1);
};
scwin.cmb_PeriodTp_2_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp_2, "VALUE", cmb_PeriodTp_2.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate_2, edt_EDate_2);
};
scwin.btn_SDate_1_onclick = function() {
    popUpCalendar2(edt_SDate_1);
};
scwin.btn_EDate_1_onclick = function() {
    popUpCalendar2(edt_EDate_1);
};
scwin.btn_SDate_2_onclick = function() {
