scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "상장폐지회사현황", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "상장폐지종목현황", "", "8");
    }
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top_1);
    $c.cm.PanelToGroupBox(panel_Top_2);
    MaxTab_01.setSelectedTabIndex(1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_2);
    scwin.fn_SetCode();

    //fn_list_sync();

};
